import { Cluster } from 'ioredis';

// Cluster seed nodes point at the masters; each master has 1 replica for failover.
const cluster = new Cluster(
  [
    { host: 'redis-master-1.internal', port: 6379 },
    { host: 'redis-master-2.internal', port: 6379 },
    { host: 'redis-master-3.internal', port: 6379 },
  ],
  {
    // scaleReads defaults to 'master' — every command, reads included,
    // is routed to the master that owns the key's hash slot.
    scaleReads: 'master',
    redisOptions: {
      password: process.env.REDIS_PASSWORD,
    },
  },
);

export class ProfileCacheService {
  /**
   * Cached, staleness-tolerant read (profile/catalog data).
   * Currently always hits the master owning this key's slot,
   * even though the value would be fine served a few hundred ms stale.
   */
  async getCachedProfile(userId: string): Promise<string | null> {
    const key = `profile:${userId}`;
    return cluster.get(key);
  }

  /**
   * Write path — must land on the master, this part is correct.
   */
  async setCachedProfile(userId: string, payload: string, ttlSeconds: number): Promise<void> {
    const key = `profile:${userId}`;
    await cluster.set(key, payload, 'EX', ttlSeconds);
  }
}

